#include <iostream>
using namespace std;

class A_Stack {
private:
    char cArray[10];
    int numItems = 0;
public:
    bool isEmpty() {
        return numItems == 0;
    }
    bool isFull() {
        return numItems == 10;
    }
    void push(char c) {
        if (isFull()) {
            cout << "Stack is full" << endl;
            return;
        }
        cArray[numItems] = c;
        numItems++;
    }
    char pop() {
        if (isEmpty()) {
            cout << "Stack is empty" << endl;
            return ' ';
        }
        return cArray[--numItems];
    }
    char top() {
        return cArray[numItems - 1];
    }
};

int main() {
    A_Stack s;
    s.push('A');
    s.push('B');
    s.push('C');
    cout << "Top: " << s.top() << endl;
    cout << "Popped " << s.pop() << endl;
    s.push('D');
    cout << "Popped " << s.pop() << endl;
    cout << "Popped " << s.pop() << endl;
    cout << "Popped " << s.pop() << endl;
    cout << "Empty: " << s.isEmpty() << endl;
    return 0;
}
